                }
                None => {
                    return Err(CliArgumentError {
                        message: "Custom charset definition ends with incomplete token '?'"
                            .to_string(),
                    });
                }
            }
        } else {
            charset.push(c);
        }
    }

    if charset.is_empty() {
        return Err(CliArgumentError {
            message: "Custom charset definition is empty".to_string(),
